__attribute__((destructor)) static void stop_profile() {
  if(!logfile) return;
  check(cuptiActivityFlushAll(0));
  uint64_t end_ns; check(cuptiGetTimestamp(&end_ns));
  row("bounds","measured run",begin_ns,end_ns);
  fclose(logfile);
}
